//! The contract between Garage's ingester and the plugins that read document types.
//!
//! `proto/garage_plugin.proto` is the contract; this crate is its Rust side. A plugin implements
//! [`Plugin`] once and is then reachable two ways:
//!
//! * in its own process, serving gRPC on a Unix-domain socket ([`server`], feature `grpc`);
//! * linked into the ingester, through a C ABI whose requests and responses are the same
//!   messages, serialized ([`ffi`]).
//!
//! The messages are generated by `protogen` and checked in, so building a plugin needs no `protoc`.

pub mod ffi;
#[cfg(all(feature = "grpc", unix))]
pub mod server;

/// The contract's messages, `garage.plugin.v1`.
#[allow(clippy::pedantic, clippy::doc_markdown)]
pub mod proto {
    include!("generated/messages/garage.plugin.v1.rs");

    #[cfg(feature = "grpc")]
    pub use super::services::*;
}

/// The generated gRPC client and server, over [`proto`].
#[cfg(feature = "grpc")]
#[allow(clippy::pedantic, clippy::doc_markdown)]
mod services {
    include!("generated/services/garage.plugin.v1.rs");
}

use proto::{ContractVersion, DescribeRequest, DescribeResponse, ExtractRequest, ExtractResponse};

/// The contract this crate implements.
pub const CONTRACT: ContractVersion = ContractVersion::ContractVersion1;

/// A plugin: one or more extractors behind `Describe` and `Extract`.
///
/// Both methods are synchronous and may take as long as reading a file takes; the gRPC server runs
/// them on a blocking thread. They must not panic on any input: a file is untrusted data. (A panic
/// is still caught at both transports and reported as a failed call.)
pub trait Plugin: Send + Sync + 'static {
    /// What this plugin reads.
    fn describe(&self, request: &DescribeRequest) -> DescribeResponse;

    /// Read one file.
    fn extract(&self, request: ExtractRequest) -> ExtractResponse;
}

impl ExtractResponse {
    /// The file's text.
    pub fn document(document: proto::Document) -> Self {
        Self { outcome: Some(proto::extract_response::Outcome::Document(document)) }
    }

    /// The file holds no text.
    pub fn no_text(reason: impl Into<String>) -> Self {
        Self { outcome: Some(proto::extract_response::Outcome::NoText(proto::NoText { reason: reason.into() })) }
    }

    /// The plugin could not read the file.
    pub fn failure(code: proto::failure::Code, message: impl Into<String>) -> Self {
        Self {
            outcome: Some(proto::extract_response::Outcome::Failure(proto::Failure {
                code: code.into(),
                message: message.into(),
            })),
        }
    }
}
